import React, { useState, useEffect } from "react";
import axios from "axios";

const Dashboard = ({ userId }) => {
  const [dashboardData, setDashboardData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchDashboardData = async () => {
      console.log("Fetching dashboard with userId:", userId);
      if (!userId) {
        setError("No userId provided");
        setLoading(false);
        return;
      }
      try {
        const response = await axios.get("http://localhost:5000/dashboard", {
          headers: { "user-id": userId },
        });
        console.log("Dashboard Response:", response.data);
        setDashboardData(response.data);
      } catch (err) {
        const errorMessage = err.response
          ? `Server error: ${err.response.status} - ${JSON.stringify(
              err.response.data
            )}`
          : `Network error: ${err.message}`;
        setError(`Failed to fetch dashboard data: ${errorMessage}`);
        console.error("Fetch error:", err.response ? err.response.data : err);
      } finally {
        setLoading(false);
      }
    };
    fetchDashboardData();
  }, [userId]);

  console.log("Dashboard render:", { loading, error, dashboardData });

  if (loading)
    return (
      <p style={{ color: "black", textAlign: "center", marginTop: "20px" }}>
        Loading...
      </p>
    );
  if (error)
    return (
      <p style={{ color: "red", textAlign: "center", marginTop: "20px" }}>
        {error}
      </p>
    );
  if (!dashboardData || !dashboardData.user)
    return (
      <p style={{ color: "black", textAlign: "center", marginTop: "20px" }}>
        No dashboard data available
      </p>
    );

  const { user, wishlist, recentActivity } = dashboardData;

  return (
    <div
      style={{
        padding: "20px",
        color: "black",
        backgroundColor: "#f0f0f0",
        minHeight: "100vh",
      }}
    >
      <h2 style={{ textAlign: "center", marginBottom: "20px" }}>
        My Dashboard
      </h2>
      <div style={{ marginBottom: "20px" }}>
        <h3>Welcome, {user.full_name || "Guest"}</h3>
        <p>Email: {user.email || "N/A"}</p>
      </div>
      <h3 style={{ fontSize: "1.5rem", marginBottom: "10px" }}>My Wishlist</h3>
      {wishlist && wishlist.length > 0 ? (
        <ul style={{ listStyle: "none", padding: 0 }}>
          {wishlist.map((house) => (
            <li
              key={house.id}
              style={{
                marginBottom: "15px",
                border: "1px solid #ddd",
                padding: "15px",
                borderRadius: "5px",
                display: "flex",
                alignItems: "center",
                backgroundColor: "#fff",
              }}
            >
              <div>
                <strong>{house.address || "N/A"}</strong>
                <p>Price: ${house.price || "N/A"}</p>
              </div>
              {house.images && house.images.length > 0 && (
                <img
                  src={`http://localhost:5000${house.images[0]}`}
                  alt="House"
                  style={{
                    width: "120px",
                    marginLeft: "20px",
                    borderRadius: "5px",
                  }}
                  onError={(e) => (e.target.src = "/fallback-image.jpg")} // Fallback image
                />
              )}
            </li>
          ))}
        </ul>
      ) : (
        <p style={{ color: "#555" }}>No items in your wishlist</p>
      )}
      <h3 style={{ fontSize: "1.5rem", marginBottom: "10px" }}>
        Recent Activity
      </h3>
      {recentActivity && recentActivity.length > 0 ? (
        <ul style={{ listStyle: "none", padding: 0 }}>
          {recentActivity.map((activity, index) => (
            <li
              key={index}
              style={{
                marginBottom: "15px",
                border: "1px solid #ddd",
                padding: "15px",
                borderRadius: "5px",
                backgroundColor: "#fff",
              }}
            >
              <strong>{activity.address || "N/A"}</strong>
              <p>Price: ${activity.price || "N/A"}</p>
            </li>
          ))}
        </ul>
      ) : (
        <p style={{ color: "#555" }}>No recent activity</p>
      )}
    </div>
  );
};

export default Dashboard;
